CREATE TABLE material_claims (material_claim_id TEXT PRIMARY KEY, application_id TEXT NOT NULL, contractor_id TEXT NOT NULL, contractor_name TEXT NOT NULL, canonical_sov_item_id TEXT NOT NULL, sov_item_description TEXT NOT NULL, material_category_code TEXT NOT NULL, claim_number TEXT NOT NULL UNIQUE, claim_date TEXT NOT NULL CHECK (claim_date GLOB '????-??-??'), claimed_amount_cents INTEGER NOT NULL CHECK (claimed_amount_cents >= 0), claim_status TEXT NOT NULL CHECK (claim_status IN ('draft','submitted','accepted','rejected','withdrawn','archived')), certification_status TEXT NOT NULL CHECK (certification_status IN ('pending_review','eligible','unsupported','excluded','not_applicable')), low_value_consumable_flag INTEGER NOT NULL DEFAULT 0 CHECK (low_value_consumable_flag IN (0,1)), incorporated_into_completed_work_flag INTEGER NOT NULL DEFAULT 0 CHECK (incorporated_into_completed_work_flag IN (0,1)), submitter_id TEXT NOT NULL, submitter_name TEXT NOT NULL, submitted_at TEXT, source_system TEXT NOT NULL DEFAULT 'UNIFIER', created_at TEXT NOT NULL);

CREATE TABLE evidence_requirements (requirement_id TEXT PRIMARY KEY, requirement_code TEXT NOT NULL UNIQUE, requirement_name TEXT NOT NULL, default_required_flag INTEGER NOT NULL CHECK (default_required_flag IN (0,1)), applies_to_stored_material_flag INTEGER NOT NULL CHECK (applies_to_stored_material_flag IN (0,1)), active_flag INTEGER NOT NULL DEFAULT 1 CHECK (active_flag IN (0,1)), exemption_rule_code TEXT, evidence_document_type TEXT NOT NULL, effective_from TEXT NOT NULL CHECK (effective_from GLOB '????-??-??'), effective_to TEXT CHECK (effective_to IS NULL OR effective_to GLOB '????-??-??'), requirement_description TEXT NOT NULL);

CREATE TABLE evidence_documents (evidence_document_id TEXT PRIMARY KEY, material_claim_id TEXT, legacy_material_claim_number TEXT, document_type TEXT NOT NULL, document_number TEXT, document_date TEXT NOT NULL CHECK (document_date GLOB '????-??-??'), document_amount_cents INTEGER CHECK (document_amount_cents IS NULL OR document_amount_cents >= 0), issuer_name TEXT NOT NULL, file_name TEXT NOT NULL, verification_status TEXT NOT NULL CHECK (verification_status IN ('unreviewed','verified','rejected','expired','superseded')), received_at TEXT NOT NULL, checksum_sha256 TEXT NOT NULL, verification_note TEXT, FOREIGN KEY (material_claim_id) REFERENCES material_claims(material_claim_id));

CREATE TABLE claim_requirement_reviews (review_id TEXT PRIMARY KEY, material_claim_id TEXT NOT NULL, requirement_id TEXT NOT NULL, evidence_document_id TEXT, review_result TEXT NOT NULL CHECK (review_result IN ('PASS','FAIL','MISSING','EXEMPT')), exemption_applied_flag INTEGER NOT NULL DEFAULT 0 CHECK (exemption_applied_flag IN (0,1)), exemption_rule_code TEXT, reviewer_id TEXT NOT NULL, reviewer_name TEXT NOT NULL, reviewed_at TEXT NOT NULL, review_note TEXT NOT NULL, UNIQUE (material_claim_id, requirement_id), CHECK ((review_result = 'EXEMPT' AND exemption_applied_flag = 1 AND exemption_rule_code IS NOT NULL) OR (review_result <> 'EXEMPT' AND exemption_applied_flag = 0)), FOREIGN KEY (material_claim_id) REFERENCES material_claims(material_claim_id), FOREIGN KEY (requirement_id) REFERENCES evidence_requirements(requirement_id), FOREIGN KEY (evidence_document_id) REFERENCES evidence_documents(evidence_document_id));

CREATE TABLE custody_locations (custody_location_id TEXT PRIMARY KEY, material_claim_id TEXT NOT NULL, location_name TEXT NOT NULL, address_line1 TEXT NOT NULL, city TEXT NOT NULL, state_code TEXT NOT NULL, postal_code TEXT NOT NULL, custody_type TEXT NOT NULL CHECK (custody_type IN ('project_site','contractor_yard','supplier_warehouse','third_party_warehouse')), owner_control_flag INTEGER NOT NULL CHECK (owner_control_flag IN (0,1)), segregated_flag INTEGER NOT NULL CHECK (segregated_flag IN (0,1)), insured_flag INTEGER NOT NULL CHECK (insured_flag IN (0,1)), title_control_flag INTEGER NOT NULL CHECK (title_control_flag IN (0,1)), verified_date TEXT NOT NULL CHECK (verified_date GLOB '????-??-??'), verified_by_id TEXT NOT NULL, control_note TEXT NOT NULL, FOREIGN KEY (material_claim_id) REFERENCES material_claims(material_claim_id));